import { Component, EventEmitter, Input, OnInit, Output, ViewChild, viewChild } from '@angular/core';
import { ContactService } from '../../../services/contact/contact.service';
import { IconComponent } from '../../icon/icon.component';
import { FormsModule } from '@angular/forms';
import { CommonModule } from '@angular/common';
import { ButtonComponent } from '../../button/button.component';
import { map } from 'rxjs';

@Component({
  selector: 'app-roles',
  standalone: true,
  imports: [CommonModule, IconComponent, FormsModule, ButtonComponent],
  templateUrl: './roles.component.html',
  styleUrl: './roles.component.scss'
})
export class RolesComponent implements OnInit {
  showroleinput: boolean = false;
  @Input() nCaseid: string;
  @Input() role_list: any = [];
  newrole: any = '';
  @Output() roleparent = new EventEmitter<any>();
  constructor(private contactService: ContactService) { }

  async ngOnInit() {
    // this.mfs.init_contact_role();

    const list = await this.contactService.getContactRole(this.nCaseid);
    this.role_list.splice(0, this.role_list.length);
    this.role_list.push(...list);
  }

  async save_role() {

    if (!this.newrole || this.newrole.trim() == '') {
      return;
    }
    var mdl: any = {};
    mdl.nCaseid = this.nCaseid;
    mdl.cRole = this.newrole;
    mdl.nCRoleid = null;
    mdl.permission = 'N';
    console.log(this.newrole);
    const res = await this.contactService.roleBuilder(mdl)
    this.showroleinput = false;
    this.newrole = '';
    this.ngOnInit();
  }

  back() {
    this.roleparent.emit('');
  }

  editRole(flag) {
    if (flag == 'E') {
      this.showroleinput = false;
    } else {
      this.role_list.map((x) => { x.iseditable = false; });
    }
  }

  async save_rolename(ev, x) {

    x.iseditable = !x.iseditable;
    if (!x.cRole || x.cRole == '') {
      return;
    }
    var mdl: any = {};
    mdl.nCaseid = this.nCaseid;
    mdl.cRole = x.cRole;
    mdl.nCRoleid = x.nCRoleid;
    mdl.permission = 'E';
    const res = await this.contactService.roleBuilder(mdl)
    this.ngOnInit();
    // this.api.post('insertupdate_contact_role', mdl, (res) => {
    //   this.ngOnInit();
    // });
  }

  async remove_role(x, ind) {
    var mdl: any = {};
    mdl.nCaseid = this.nCaseid;
    mdl.cRole = x.cRole;
    mdl.nCRoleid = x.nCRoleid;
    mdl.permission = 'D';
    const res = await this.contactService.roleBuilder(mdl)
    this.ngOnInit();
    // this.api.get('insertupdate_contact_role', mdl, (res) => {
    //   if (res[0]["msg"] == 1) {
    //     this.mfs.role_list.splice(ind, 1);
    //   } else {
    //     this.api.showError(res[0]["value1"]);
    //   }
    // })
  }


  addnewrole() {

    this.showroleinput = !this.showroleinput;
    if (this.showroleinput) {
      var input = document.getElementById('roleinput');
      setTimeout(() => {
        input.focus();
      }, 100);
      this.editRole('N');
    }
  }
}
