  ngOnChanges(changes) {
    if (changes['editable_list'] && this.cPermission == 'E') {
      // console.log('step-2', changes['editable_list'].currentValue);
      this.editable_list = changes['editable_list'].currentValue;
      this.prefillFormOnEdit();
    }
  }

  onValueChanged(e) {

    this.mobileValue;
    this.currnet_countrycode = this.mobileValue.countryCode;
    this.frm.patchValue({
      cMobile: this.mobileValue.number
    })
  }

  bindCurrentTimezone() {
    const tmzone = Intl.DateTimeFormat().resolvedOptions().timeZone;
    const Tzone = this.timezone.find(m => m.jOther.includes(tmzone));
    this.usrtmzone = Tzone;
    if (Tzone) {
      this.frm.patchValue({
        nTZid: Tzone.nValue
      })
    }
  }

  async initLists() {
    this.role_list = await this.contactService.getContactCaserolelist(this.nCaseid);
    this.party_list = await this.commonService.getCode(22);
    this.company_list = await this.contactService.getContactCompany(this.nCaseid);
    //Preselect pill texts when editing
    if (this.editable_list?.nCompanyid) {
      const c = this.company_list.find((x: any) => x.nCompanyid === this.editable_list.nCompanyid);
      if (c) this.selectedCompanyText = c.cCompany;
    }
    this.crd.detectChanges();
  }


  async gettimezone(isUpdate?) {

    this.timezone = await this.commonService.getCode(1);

    if (!isUpdate) return;

    var tmzone = Intl.DateTimeFormat().resolvedOptions().timeZone;

    var idn = this.timezone.findIndex(m => m.jOther.includes(tmzone))
    if (idn > -1) {
      this.frm.patchValue({
        nTZid: this.timezone[idn].nValue.toString()
      })
    }
    var obj: any = this.timezone[idn];
    this.usrtmzone = obj;
    this.chngtmzone = false;


  }

  ngOnDestroy(): void {
    this.editable_list = null;
  }


