    // trim firstname and lastname before validation
    const currentFname = this.frm.get('cFname')?.value;
    const currentLname = this.frm.get('cLname')?.value;

    if (currentFname) {
      this.frm.patchValue({
        cFname: currentFname.trim()
      });
    }

    if (currentLname) {
      this.frm.patchValue({
        cLname: currentLname.trim()
      });
    }

    // console.log('onsubmit', this.frm.value, this.frm.valid);

    if (this.frm.invalid || this.isTagExists) {
      return;
    }
    var model: any = {};
