import { Component, EventEmitter, Input, OnInit, Output } from '@angular/core';
import { ContactService } from '../../../services/contact/contact.service';
import { TostbarService } from '../../../../core/services/tost/tostbar.service';
import { IconComponent } from '../../icon/icon.component';
import { FormsModule } from '@angular/forms';
import { CommonModule } from '@angular/common';
import { ButtonComponent } from '../../button/button.component';
@Component({
  selector: 'app-company',
  standalone: true,
  imports: [CommonModule,IconComponent,FormsModule,ButtonComponent],
  templateUrl: './company.component.html',
  styleUrl: './company.component.scss'
})
export class CompanyComponent implements OnInit {

  @Output() roleparent = new EventEmitter<any>();
  showcompinput: boolean = false;
  newcomp: any = '';
  @Input() nCaseid: string;
  @Input() company_list: any = [];
  constructor(private contactService: ContactService, private tost: TostbarService) { }

  async ngOnInit() {
    const list = await this.contactService.getContactCompany(this.nCaseid);
    this.company_list.splice(0, this.company_list.length);
    this.company_list.push(...list);
  }
  back() {
    this.roleparent.emit('');
  }

  async save_comp() {

    if (!this.newcomp || this.newcomp.trim() == '') {
      return;
    }
    var mdl: any = {};
    mdl.nCaseid = this.nCaseid;
    mdl.cCompany = this.newcomp;
    mdl.nCompanyid = null;
    mdl.permission = 'N';
    const res = await this.contactService.companyBuilder(mdl);
    this.showcompinput = false;
    this.newcomp = '';
    // this.api.post('insertupdate_contact_company', mdl, (res) => {
    //   this.showcompinput = false;
    //   this.newcomp = '';
    this.ngOnInit();
    // });
  }
  async save_rolename(ev, x) {

    x.iseditable = !x.iseditable;
    if (!x.cCompany || x.cCompany == '') {
      return;
    }

    var mdl: any = {};
    mdl.nCaseid = this.nCaseid;
    mdl.cCompany = x.cCompany;
    mdl.nCompanyid = x.nCompanyid;
    mdl.permission = 'E';

    const res = await this.contactService.companyBuilder(mdl);


    // this.api.get('insertupdate_contact_company', mdl, (res) => {
    this.ngOnInit();
    // });



  }
  async remove_comp(x, ind) {
    var mdl: any = {};
    mdl.nCaseid = this.nCaseid;
    mdl.nCompanyid = x.nCompanyid;
    mdl.cCompany = x.cCompany;
    mdl.nCompanyid = x.nCompanyid;
    mdl.permission = 'D';
    // this.api.get('insertupdate_contact_company', mdl, (res) => {

    const res = await this.contactService.companyBuilder(mdl);
    if (res["msg"] == 1) {
      this.company_list.splice(ind, 1);
    } else {
      this.tost.openSnackBar(res[0]["value1"], 'E');
    }
    // })
  }
  addnewcomp() {
    this.showcompinput = !this.showcompinput;
    if (this.showcompinput) {
      var input = document.getElementById('compinput');
      setTimeout(() => {
        input.focus();
      }, 100);
    }
  }

}